svg.script:
(function () {
  var roomEls = Array.prototype.slice.call(document.querySelectorAll('.map-room'));
  var hud = document.getElementById('room-hud');
  var hudTitle = document.getElementById('room-hud-title');
  var hudZone = document.getElementById('room-hud-zone');
  var hudKicker = document.getElementById('room-hud-kicker');
  function clearSelection() {
    roomEls.forEach(function (el) { el.classList.remove('is-selected'); });
    if (hud) hud.classList.add('is-hidden');
  }
  function selectRoom(el) {
    clearSelection();
    el.classList.add('is-selected');
    var room = el.getAttribute('data-room') || 'Room';
    var zone = el.getAttribute('data-zone') || 'Salt Palace';
    var lvl = el.getAttribute('data-level') || '';
    if (hudTitle) hudTitle.textContent = room.indexOf('HALL-') === 0 ? 'Hall ' + room.slice(5) : room === 'BALLROOM' ? 'Grand Ballroom' : room;
    if (hudZone) hudZone.textContent = (lvl ? 'Level ' + lvl + ' · ' : '') + zone;
    if (hudKicker) hudKicker.textContent = room === '260A/B' ? 'SENSORY-FRIENDLY SPACE' : 'ROOM SELECTED';
    if (hud) {
      // Pop the label up right next to the room instead of a fixed corner
      var b = el.getBBox();
      hud.setAttribute('transform', 'translate(' + (b.x + b.width + 14) + ' ' + Math.max(0, b.y - 20) + ')');
      hud.classList.remove('is-hidden');
    }
  }
  // Pan so a room sits a bit left of center (the talk card covers the right side)
  function centerOn(el) {
    var b = el.getBBox();
    var vb = readViewBox();
    svgRoot.setAttribute('viewBox', [b.x + b.width / 2 - vb[2] * 0.4, b.y + b.height / 2 - vb[3] * 0.5, vb[2], vb[3]].join(' '));
  }
  function setLevel(level) {
    document.querySelectorAll('.level-group').forEach(function (group) {
      group.classList.toggle('is-active', group.getAttribute('data-level') === String(level));
    });
    document.documentElement.setAttribute('data-active-level', String(level));
    clearSelection();
  }
  window.setSaltPalaceLevel = setLevel;
  // ---- Click-and-drag to pan the floor plan (moves the viewBox) ----
  var svgRoot = document.documentElement;
  var homeViewBox = svgRoot.getAttribute('viewBox');
  var drag = null;          // { x, y, vb: [x, y, w, h] } while the pointer is down
  var dragMoved = false;    // true once the pointer moved past the click threshold
  svgRoot.style.cursor = 'grab';

  function readViewBox() {
    return svgRoot.getAttribute('viewBox').split(/[\s,]+/).map(Number);
  }
  svgRoot.addEventListener('pointerdown', function (event) {
    if (event.button !== 0) return;
    drag = { x: event.clientX, y: event.clientY, vb: readViewBox() };
    dragMoved = false;
  });
  svgRoot.addEventListener('pointermove', function (event) {
    if (!drag) return;
    var dx = event.clientX - drag.x;
    var dy = event.clientY - drag.y;
    if (!dragMoved && Math.abs(dx) + Math.abs(dy) < 5) return; // still a click, not a drag
    if (!dragMoved) {
      dragMoved = true;
      svgRoot.setPointerCapture(event.pointerId);
      svgRoot.style.cursor = 'grabbing';
    }
    var ctm = svgRoot.getScreenCTM();          // screen pixels per SVG unit
    var scale = ctm ? ctm.a : 1;
    svgRoot.setAttribute('viewBox', [drag.vb[0] - dx / scale, drag.vb[1] - dy / scale, drag.vb[2], drag.vb[3]].join(' '));
  });
  function endDrag() {
    drag = null;
    svgRoot.style.cursor = 'grab';
  }
  svgRoot.addEventListener('pointerup', endDrag);
  svgRoot.addEventListener('pointercancel', endDrag);
  // A drag that ends on a room must not count as clicking that room
  document.addEventListener('click', function (event) {
    if (dragMoved) {
      event.stopPropagation();
      event.preventDefault();
      dragMoved = false;
    }
  }, true);
  // Double-click empty space to re-center
  svgRoot.addEventListener('dblclick', function (event) {
    if (!event.target.closest || !event.target.closest('.map-room')) svgRoot.setAttribute('viewBox', homeViewBox);
  });
  window.resetSaltPalaceView = function () { svgRoot.setAttribute('viewBox', homeViewBox); };

  // Let the app highlight a room by id (e.g. after picking a search result)
  window.selectSaltPalaceRoom = function (roomId) {
    var el = roomEls.filter(function (r) { return r.getAttribute('data-room') === String(roomId); })[0];
    if (el) {
      centerOn(el);
      selectRoom(el);
      if (hudKicker) hudKicker.textContent = 'TALK LOCATION';
    }
    return Boolean(el);
  };
  roomEls.forEach(function (el) {
    el.addEventListener('click', function (event) {
      event.stopPropagation();
      selectRoom(el);
    });
    el.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        selectRoom(el);
      }
    });
  });
  document.addEventListener('click', function (event) {
    if (!event.target.closest || !event.target.closest('.map-room')) clearSelection();
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') clearSelection();
  });
  setLevel(2);
})();
